"""Runs the mandate strategy from input data through model training and reporting.

The final challenge endows US$1bn at the start of the out-of-sample period
and the fund compounds from there (Instructions 3.1, 3.3).
"""

# Python 3.13 dependencies (also listed in requirements.txt):
# numpy==2.5.3 pandas==3.0.2 pyarrow==21.0.0 scipy==1.17.1
# xgboost==3.4.1 torch==2.14.0 matplotlib==3.10.9

import argparse
import sys
import tempfile
from pathlib import Path

