        '        "permno",\n'
        '        "eom",\n'
        '        "prc",\n'
        '        "size_grp",\n'
        '        "dolvol_126d",\n'
        '        "me",\n'
        '        "ret_exc_lead1m",\n'
        '        "gics",\n'
        '        "beta_60m",\n'
