        '    u["return_month"] = pd.to_datetime(u.eom).dt.to_period("M") + 1\n'
        '    u["sector"] = u.gics.astype("string").str[:2].fillna("na")\n'
        '    u["size_grp"] = u.size_grp.astype("string")\n'
        '    quotes = u.loc[u.prc.notna() & u.prc.abs().gt(0), ["permno", "eom", "prc"]].copy()\n'
